typedef struct xn_Cls_SC xn_Cls_SC;

typedef struct { rt_header hdr; size_t len; size_t cap; int64_t *data; } xn_arr_i;

typedef struct { rt_header hdr; size_t len; size_t cap; rt_string * *data; } xn_arr_s;

typedef struct { rt_header hdr; size_t len; size_t cap; xn_Cls_DF * *data; } xn_arr_o_DF;

typedef struct { rt_header hdr; size_t len; size_t cap; xn_Cls_N * *data; } xn_arr_o_N;

typedef struct { rt_header hdr; size_t len; size_t cap; xn_Cls_SC * *data; } xn_arr_o_SC;

typedef struct xn_Cls_AP xn_Cls_AP;
typedef struct xn_Cls_DF xn_Cls_DF;
typedef struct xn_Cls_EM xn_Cls_EM;
typedef struct xn_Cls_N xn_Cls_N;
typedef struct xn_Cls_SC xn_Cls_SC;

static xn_Cls_AP *xn_Cls_AP_new(rt_string * xn_p_t);
static void xn_Cls_AP_new_init(xn_Cls_AP *o, rt_string * xn_p_t);
static xn_Cls_DF *xn_Cls_DF_new(void);
static void xn_Cls_DF_new_init(xn_Cls_DF *o);
static xn_Cls_EM *xn_Cls_EM_new(void);
static void xn_Cls_EM_new_init(xn_Cls_EM *o);
static xn_Cls_N *xn_Cls_N_new(void);
static void xn_Cls_N_new_init(xn_Cls_N *o);
