int main(int argc, char **argv) {
    xrt_runtime_init();
    xn_init_vtables();
    xn_init_enums();
    xn_init_globals();
    xn_arr_s *xn_args = xn_arr_s_new((size_t)(argc > 1 ? argc - 1 : 0));
    for (int i = 1; i < argc; i++) {
        rt_string *xn_av = rt_string_from_c(argv[i]);
        xn_arr_s_push(xn_args, xn_av);
        rt_release(xn_av);
    }
    int64_t xn_r = xn_main(xn_args);
    rt_gc_collect();
    rt_quarantine_flush();
    return (int)xn_r;
}
